import json,os
r=json.load(open('screenshots/browser-check.json'))
checks={'production_build':'passed; dist/index.html exists','browser_report':'screenshots/browser-check.json','screenshots':['screenshots/desktop.png','screenshots/mobile.png'],'viewports':[], 'script_errors':r['errors'],'console_errors':r['consoleErrors'],'failed_requests':r['failedRequests']}
for v in r['viewports']:
 checks['viewports'].append({'size':f"{v['width']}x{v['height']}",'all_five_dots':'passed' if len(v['slides'])==5 else 'failed','keyboard':'passed' if all(k['passed'] for k in v['keyboard']) else 'failed','persistent_video_elements':v['persistentVideos'],'layout_overflow':any(s['horizontalOverflow'] or s['verticalOverflow'] or s['textOutside'] for s in v['slides']),'video_playback':[{'slide':i+1,'advanced':x['currentTime']>0,'paused':x['paused'],'ready_state':x['readyState'],'error':x['error']} for i,x in enumerate(v['videos'])]})
result={'title':'Investor Deck','id':'deck-investor','status':'ready','build_command':'docker run --rm -u 1000:1000 -e HOME=/tmp -v "$PWD:/work" -w /work --entrypoint sh louislam/uptime-kuma:2 -c \'npm ci && npm run build\'','checks':checks,'asset_issues':[{'asset':'Aeonik','issue':'No font file or URL supplied; CSS requests Aeonik and falls back to sans-serif. Exact typography requires a licensed font.'},{'asset':'Logo SVG','issue':'Original path data absent. Locally recreated Viktory wordmark in src/assets/logo.svg.'},{'asset':'Chart PNG','issue':'Original PNG absent. Locally generated gradient fill; reproducible with scripts/generate-chart.py.'},{'asset':'Reference preview','issue':'Design-specific optional WebP not present. Original screenshot comparison unavailable.'}],'notes':['Built with React, Tailwind CSS v4, motion/react, and hls.js. All five slides and videos remain mounted.','All five exact Mux streams loaded and advanced on desktop and mobile. Mobile streams 1 and 4 had readyState 2 at final sampling; external streams may buffer. Local exact-video posters cover startup.','Five individual slide screenshots per viewport are included in screenshots/.','Desktop and mobile checks: zero script/console errors or failed requests; no page/text overflow; all five navigation keys passed while a dot had focus.','Production base: /motionsites-results/deck-investor/. dist/ is ready for review; not deployed or pushed.','Non-fatal Motion directives and bundle-size warnings are retained in screenshots/build.log.','Only this project was implemented. No agents or other sessions were created.']}
assert os.path.isfile('dist/index.html') and not r['errors'] and not r['consoleErrors']
assert all(v['keyboard']=='passed' and not v['layout_overflow'] for v in checks['viewports'])
open('result.json','w').write(json.dumps(result,indent=2)+'\n')
